#!/usr/bin/env python3
"""Invalidate private Docker compilation trees when their source/toolchain changes."""

import argparse
import hashlib
import json
from pathlib import Path
import shutil
import stat
import subprocess
import tempfile


CACHE_ROOT = Path("/workspace/build")
MARKER = ".heaven-docker-cache.json"
# These are generated by the shared release helpers, never arbitrary user paths.
# Downloaded tools/sources, Gradle dependency caches and Android signing keys stay.
COMPILATION_TREES = (
    "tools", "asset-tools", "renderer", "renderer-debug",
    "renderer-android-arm64-v8a", "renderer-android-x86_64",
    "android-host-renderer", "android-host-tools", "android-gradle",
    "android-package", "packages",
)


def source_fingerprint(source):
    """Hash names, file bytes, executable permissions and internal symlink targets."""
    source = source.resolve(strict=True)
    digest = hashlib.sha256()
    for path in sorted(source.rglob("*")):
        info = path.lstat()
        name = path.relative_to(source).as_posix()
        if stat.S_ISLNK(info.st_mode):
            target = path.readlink()
            if target.is_absolute() or not path.resolve(strict=True).is_relative_to(source):
                raise ValueError(f"Source symlink escapes context: {name}")
            entry = [name, "symlink", target.as_posix()]
        elif stat.S_ISREG(info.st_mode):
            content = hashlib.sha256()
            with path.open("rb") as stream:
                for block in iter(lambda: stream.read(1024 * 1024), b""):
                    content.update(block)
            entry = [name, "file", stat.S_IMODE(info.st_mode), content.hexdigest()]
        elif stat.S_ISDIR(info.st_mode):
            continue
        else:
            raise ValueError(f"Unsupported source file type: {name}")
        digest.update(json.dumps(entry, ensure_ascii=True, separators=(",", ":")).encode())
        digest.update(b"\n")
    return digest.hexdigest()


def toolchain_identity(platform):
    """Fail closed if the declared container compiler/package identity is missing."""
    commands = {
        "packages": ["dpkg-query", "-W", "-f=${binary:Package}\t${Version}\t${Architecture}\n"],
        "clang": ["clang-21", "--version"],
        "cmake": ["cmake", "--version"],
        "ninja": ["ninja", "--version"],
    }
    identity = {
        name: subprocess.run(command, text=True, capture_output=True, check=True,
                             timeout=30).stdout
        for name, command in commands.items()
    }
    if platform == "android":
        # Includes the exact JDK/SDK/NDK pins and installed SDK component versions.
        identity["android"] = json.loads(Path("/opt/android-toolchain.json").read_text())
    return identity


def prepare_cache(source, cache, *, platform, target, toolchain):
    """Prepare a trusted private cache; callers own exclusive access while building."""
    source = Path(source).resolve(strict=True)
    cache = Path(cache)
    if cache.is_symlink():
        raise ValueError("The compilation cache root must not be a symlink")
    cache = cache.resolve()
    if source == cache or source in cache.parents or cache in source.parents:
        raise ValueError("Source context and compilation cache must be separate trees")
    state = {
        "schema_version": 1,
        "source_sha256": source_fingerprint(source),
        "platform": platform,
        "target": target,
        "toolchain": toolchain,
    }
    state["fingerprint"] = hashlib.sha256(json.dumps(
        state, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    marker = cache / MARKER
    if marker.is_symlink():
        raise ValueError("The cache state marker must not be a symlink")
    try:
        previous = json.loads(marker.read_text())
    except (FileNotFoundError, json.JSONDecodeError, UnicodeDecodeError):
        previous = None
    if isinstance(previous, dict) and previous.get("fingerprint") == state["fingerprint"]:
        print("Docker compilation cache matches the complete source/toolchain fingerprint")
        return {"invalidated": False, "removed": [], "state": state}

    cache.mkdir(parents=True, exist_ok=True)
    removed = []
    for name in COMPILATION_TREES:
        path = cache / name
        if path.is_symlink():
            path.unlink()  # Never follow a link outside the private cache.
        elif path.is_dir():
            shutil.rmtree(path)
        elif path.exists():
            path.unlink()
        else:
            continue
        removed.append(name)
    # Record the input generation BEFORE compiling. If that build fails and the
    # caller reverts to earlier sources, the next invocation must invalidate its
    # partial outputs instead of trusting an old successful-build marker.
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=cache,
                                         prefix=MARKER + ".", delete=False) as stream:
            temporary = Path(stream.name)
            json.dump(state, stream, indent=2, sort_keys=True)
            stream.write("\n")
        temporary.replace(marker)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)
    print("Source/toolchain changed; cleared compilation trees: " +
          (", ".join(removed) if removed else "none present"))
    return {"invalidated": True, "removed": removed, "state": state}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source-root", type=Path, required=True)
    parser.add_argument("--platform", choices=("linux", "android"), required=True)
    parser.add_argument("--target", required=True)
    args = parser.parse_args()
    # This command is internal to the Dockerfile, not a host cache deletion tool.
    if CACHE_ROOT.is_symlink() or CACHE_ROOT.resolve() != CACHE_ROOT:
        parser.error("Expected the private Docker cache at /workspace/build")
    # Bind mounts can share st_dev with their parent, so Path.is_mount() cannot
    # reliably recognize BuildKit's cache mount. Linux mountinfo can.
    mountinfo = Path("/proc/self/mountinfo")
    mounted = mountinfo.is_file() and any(
        len(fields) > 4 and fields[4] == str(CACHE_ROOT)
        for fields in (line.split() for line in mountinfo.read_text().splitlines()))
    if not mounted:
        parser.error("Expected /workspace/build to be a mounted Docker compilation cache")
    targets = {"linux": {"portable", "zen1", "zen2", "zen3", "zen4", "zen5"},
               "android": {"arm64-v8a", "x86_64"}}
    if args.target not in targets[args.platform]:
        parser.error("Invalid target for selected platform")
    prepare_cache(args.source_root, CACHE_ROOT, platform=args.platform, target=args.target,
                  toolchain=toolchain_identity(args.platform))


if __name__ == "__main__":
    main()
